import ast, asyncio, hashlib, importlib.metadata as metadata, inspect, json, pathlib, subprocess, sys
from typing import TypedDict
from pydantic import BaseModel, ConfigDict, ValidationError
from fastapi import FastAPI
from fastapi.testclient import TestClient
from langgraph.graph import StateGraph, START, END
from langgraph.func import task
from langgraph.checkpoint.memory import InMemorySaver
from kodezart.domain.dispatch import select_top_ranked, live_blocker
from kodezart.domain.topology import plan_topology
from kodezart.types.domain.operation import OperationConfig, LifecycleStage, QueueState, ScopeLabel
from kodezart.types.domain.run_event import RunEventKind, RunEventEffect, DERIVED_RUN_EVENTS, SILENT_STATE_EVENTS
from kodezart.types.domain.dispatch import ExclusionClause
from kodezart.types.domain.tracker import WorkflowStateKind
from tests.fakes import make_tracker_issue
from tests.run_events import RUN_EVENT_STATES

out = {}
expected = {"fastapi":"0.135.1","pydantic":"2.12.5","langgraph":"1.0.10","langgraph-checkpoint":"4.0.1"}
out["versions"] = {k: metadata.version(k) for k in expected}
assert out["versions"] == expected
out["python"] = sys.executable
out["tested_sha"] = subprocess.check_output(["git","rev-parse","HEAD"],text=True).strip()
assert out["tested_sha"] == "55a87a5009e1816d1d87c130a7f46a2a83a9f37e"
canonical=pathlib.Path("/private/tmp/kodezart-v03-recovery-integration")
out["canonical_worktree_head_at_probe"] = subprocess.check_output(["git","-C",str(canonical),"rev-parse","HEAD"],text=True).strip()
out["canonical_sha"] = "c96895e18d3137544ea30d18188006118ee8a6e5"
same_files=["src/kodezart/domain/dispatch.py","src/kodezart/domain/issue_tree.py","src/kodezart/domain/topology.py","src/kodezart/types/domain/operation.py","src/kodezart/types/domain/run_event.py","src/kodezart/types/domain/dispatch.py","src/kodezart/services/tracker_lifecycle.py","src/kodezart/services/fire_dispatcher.py","src/kodezart/chains/scope_walker.py","src/kodezart/services/scope_planning.py","src/kodezart/main.py","src/kodezart/core/checkpointer.py"]
out["same_source_sha256"]={}
for name in same_files:
 a=pathlib.Path(name).read_bytes();b=subprocess.check_output(["git","-C",str(canonical),"show",out["canonical_sha"]+":"+name])
 assert a==b,name
 out["same_source_sha256"][name]=hashlib.sha256(a).hexdigest()

a,b = make_tracker_issue("A"), make_tracker_issue("B")
one=select_top_ranked([a,b],draw=lambda tied:tied[0])
two=select_top_ranked([a,b],draw=lambda tied:tied[-1])
assert one.winner_key=="A" and two.winner_key=="B" and one.tied==two.tied
outside=select_top_ranked([a,b],draw=lambda tied:"OUTSIDE")
assert outside.winner_key=="OUTSIDE"
out["selection"]={"legal_draws":[one.winner_key,two.winner_key],"tied":one.tied,"unvalidated_draw":outside.winner_key}
out["dispatch_inventory"]={"pure_clauses":[n.name for n in ast.parse(pathlib.Path("src/kodezart/domain/dispatch.py").read_text()).body if isinstance(n,ast.FunctionDef) and (n.name.startswith("clause_") or n.name=="live_blocker")],"exclusion_members":[e.value for e in ExclusionClause]}
assert len(out["dispatch_inventory"]["pure_clauses"])==8
assert len(ExclusionClause)==12
consumer=ast.parse(pathlib.Path("src/kodezart/services/fire_dispatcher.py").read_text())
predicate=next(n for n in ast.walk(consumer) if isinstance(n,ast.AsyncFunctionDef) and n.name=="_exclude")
ret=next(n for n in predicate.body if isinstance(n,ast.Return))
out["dispatch_inventory"]["service_stages"]=len(ret.value.values)
assert out["dispatch_inventory"]["service_stages"]==10

dependent=make_tracker_issue("C",blocked_by=["B"])
openblock=make_tracker_issue("B",state_kind=WorkflowStateKind.UNSTARTED)
closedblock=make_tracker_issue("B",state_kind=WorkflowStateKind.COMPLETED)
def ready(blocker, blocking=None):
 return [e.issue.issue_key for e in plan_topology(issues=[dependent,blocker],candidate_keys=frozenset({"C"}),blocking_issue_keys=blocking).ready]
assert ready(openblock)==[] and ready(closedblock)==["C"]
assert ready(openblock,frozenset())==["C"]
assert ready(closedblock,frozenset({"B"}))==[]
out["topology_dual_rule"]={"default_open":ready(openblock),"default_closed":ready(closedblock),"explicit_empty_open":ready(openblock,frozenset()),"explicit_blocking_closed":ready(closedblock,frozenset({"B"}))}
assert live_blocker(dependent,blockers={}) is None
try:plan_topology(issues=[dependent],candidate_keys=frozenset({"C"}))
except ValueError as e:out["missing_blocker"]={"predicate":None,"topology_error":str(e)}
else:raise AssertionError("missing topology facts accepted")

operation=OperationConfig(operation_name="probe",workspace="probe",run_event_states=dict(RUN_EVENT_STATES))
original=operation.run_event_states["pr_opened"]
operation.run_event_states["pr_opened"]=LifecycleStage.DONE
operation.require_run_event_table()
out["event_table"]={"count":len(RunEventKind),"derived_count":len(DERIVED_RUN_EVENTS),"silent_count":len(SILENT_STATE_EVENTS),"named_stage_count":len(RunEventKind)-len(DERIVED_RUN_EVENTS)-len(SILENT_STATE_EVENTS),"original_pr_opened":original,"valid_alternative_pr_opened":operation.run_event_states["pr_opened"],"frozen_nested_dict_mutable":True}
bad=operation.model_copy(update={"run_event_states":{"rogue":"invalid"}})
assert bad.run_event_states=={"rogue":"invalid"}
try:bad.require_run_event_table()
except ValueError as e:out["event_table"]["explicit_revalidation_rejects_copy"]=type(e).__name__
else:raise AssertionError("invalid table accepted")
out["event_table"]["copy_update_unvalidated"]=True
assert LifecycleStage.DONE==QueueState.DONE and LifecycleStage.DONE is not QueueState.DONE
out["cross_enum_string_equality"]={"done_equal":LifecycleStage.DONE==QueueState.DONE,"done_identical":LifecycleStage.DONE is QueueState.DONE,"approved_equal":ScopeLabel.APPROVED==QueueState.APPROVED}

class Reply(BaseModel):
 model_config=ConfigDict(extra="forbid")
 decision: str
 evidence: str
valid_a=Reply(decision="A",evidence="stub evidence")
valid_b=Reply(decision="B",evidence="stub evidence")
assert valid_a!=valid_b
out["typed_proposal"]={"both_validate":True,"different_decisions":True,"real_model_called":False}
effects=[]
api=FastAPI()
class NumberResponse(BaseModel):
 count:int
@api.post("/probe",response_model=NumberResponse)
def endpoint():
 effects.append("external-effect-analogue")
 return {"count":"invalid"}
with TestClient(api,raise_server_exceptions=False) as client:
 response=client.post("/probe")
assert response.status_code==500 and len(effects)==1
out["fastapi_response_validation"]={"status":response.status_code,"effect_count":len(effects)}

class GraphState(TypedDict):
 value: str
raw_effects=[]
def raw_node(state):
 raw_effects.append("effect")
 if len(raw_effects)==1:raise RuntimeError("after-effect")
 return {"value":"resumed"}
builder=StateGraph(GraphState);builder.add_node("writer",raw_node)
builder.add_edge(START,"writer");builder.add_edge("writer",END)
graph=builder.compile(checkpointer=InMemorySaver())
cfg={"configurable":{"thread_id":"raw-effect"}}
try:graph.invoke({"value":"start"},cfg)
except RuntimeError:pass
else:raise AssertionError("expected failure")
assert graph.invoke(None,cfg)["value"]=="resumed"
assert len(raw_effects)==2
out["langgraph_raw_effect_resume"]={"effects":len(raw_effects)}

cached_calls=[];node_calls=[];seen=[]
@task
def non_deterministic_result():
 value="decision-"+str(len(cached_calls)+1)
 cached_calls.append(value)
 return value
def typed_node(state):
 node_calls.append("node")
 value=non_deterministic_result().result()
 seen.append(value)
 if len(node_calls)==1:raise RuntimeError("after-task-before-node-checkpoint")
 return {"value":value}
builder=StateGraph(GraphState);builder.add_node("decision",typed_node)
builder.add_edge(START,"decision");builder.add_edge("decision",END)
graph=builder.compile(checkpointer=InMemorySaver())
cfg={"configurable":{"thread_id":"cached-decision"}}
try:graph.invoke({"value":"start"},cfg)
except RuntimeError:pass
else:raise AssertionError("expected failure")
assert graph.invoke(None,cfg)["value"]=="decision-1"
assert len(node_calls)==2 and len(cached_calls)==1 and seen==["decision-1"]*2
out["langgraph_cached_nondeterminism"]={"node_calls":len(node_calls),"task_calls":len(cached_calls),"results":seen,"real_model_called":False}
print(json.dumps(out,indent=2,default=str))
